sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float beat;
uniform float beatTime;
uniform float beatIndex;
uniform float strength;
uniform float decay;
uniform float beats;
uniform float offset;
uniform float bpm;
uniform float frequency;
float hash(float n) { return fract(sin(n * 12.9898 + 4.1414) * 43758.5453); }
half4 main(float2 xy) {
    float a = hash(beatIndex) * 6.2831853;
    float w = sin(beatTime * frequency * 6.2831853);
    float v = sin(beatTime * frequency * 8.6079 + 1.7);
    float2 d = (float2(cos(a), sin(a)) * w + float2(-sin(a), cos(a)) * v * 0.5) * strength * beat * min(size.x, size.y);
    return image.eval(xy - d);
}
